"""docich#5127 follow-up: consume ``roster_read_due`` in every chapter.

PR #5129 (v1387) registered the bounded destination-roster read for a recall
whose input was sent but whose picker never closed (``arrival_unconfirmed``).
The only general consumption was chapter 9's corridor probe, and the boss
wave honoured a due solely for a blind/kept ``launch_probe``'s own source —
in the reproduction chapter (ch10) the due expired unread and the recalled
general stayed unaccounted. ``interim_candidates`` now mints one read-only
roster probe for the due castle, so the sortie menu's list read — the arrival
receipt — actually launches in any chapter.
"""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.strategy import replan, routes
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world

ANY = replan.MOVE_ANY_GENERAL

BOSS = chart.boss_castle(10)
NORMAL = sorted(set(chart.CASTLE_NAMES[10]) - {BOSS})
DUE = 'ファルゲ'


def memory(captured=NORMAL, garrison=None, chapter=10, **fields):
    mem = {'chapter': chapter, 'month': '42-6', 'tick': 100,
           'captured': list(captured), 'lost': [], 'orders': {},
           'garrison': {c: None for c in captured},
           'world': {'sorties': {}},
           '_records': [], 'house_eggs': {}, 'general_location_unknown': []}
    if garrison:
        _world(mem)['garrison'].update(garrison)
    mem.update(fields)
    return mem


def candidates(mem):
    return list(replan.interim_candidates(mem).values())


def test_a_due_castle_mints_a_read_only_roster_probe():
    # ch10 reproduction: the whole road is held, the boss waves are the plan,
    # and a recall's arrival confirmation still has to open the list. The due
    # castle's last read came back empty, so no other order is planned out of
    # it — the roster probe is what re-reads it.
    mem = memory(garrison={DUE: []},
                 roster_read_due={DUE: 100})
    probe = next((o for o in candidates(mem) if o.get('roster_probe')), None)
    assert probe is not None, 'the due roster read must be planned'
    assert probe['source'] == DUE
    assert probe['general'] == ANY
    assert probe.get('source_probe') is True
    assert DUE in (mem.get('roster_read_due') or {}), \
        'the mint does not consume the due — the complete read does'


def test_the_due_probe_leads_the_plan():
    """The arrival receipt may not starve behind the boss waves."""
    mem = memory(garrison={DUE: []},
                 roster_read_due={DUE: 100})
    first = candidates(mem)[0]
    assert first.get('roster_probe') is True and first['source'] == DUE


def test_the_probe_is_startable_from_the_recorded_garrison():
    mem = memory(garrison={DUE: ['リーキ']},          # one measured defender
                 roster_read_due={DUE: 100})
    probe = next(o for o in candidates(mem) if o.get('roster_probe'))
    from docich.hanjuku_speedrun import hanjuku_chart_adjust as chart_adjust
    assert chart_adjust.startable(probe, replan._adjust_situation(mem)) is None


def test_a_future_due_waits_for_the_walk():
    """The due is a due *time*: read after the recalled general can arrive."""
    mem = memory(garrison={DUE: []},
                 roster_read_due={DUE: 100 + 180})
    assert not [o for o in candidates(mem) if o.get('roster_probe')]
    mem['tick'] += 180
    probe = next((o for o in candidates(mem) if o.get('roster_probe')), None)
    assert probe is not None and probe['source'] == DUE


def test_a_stale_due_is_dropped_not_probed():
    """A due older than the TTL must not keep minting an unbudgeted probe."""
    mem = memory(garrison={DUE: []},
                 roster_read_due={DUE: 100 - routes.ROSTER_READ_DUE_TTL - 1})
    assert not [o for o in candidates(mem) if o.get('roster_probe')]
    assert DUE not in (mem.get('roster_read_due') or {})


def test_an_unowned_due_castle_is_not_probed():
    mem = memory(captured=[c for c in NORMAL if c != 'ケントルム'],
                 roster_read_due={'ケントルム': 100})
    assert not [o for o in candidates(mem) if o.get('roster_probe')
                and o.get('source') == 'ケントルム']


def test_the_due_probe_is_chapter_agnostic():
    """The consumption is the shared interim path, not a chapter-9 rule."""
    owned = [c for c in chart.castles(6) if not chart.is_boss_castle(c)]
    mem = memory(chapter=6, captured=owned,
                 garrison={'カバルッサ': []},
                 roster_read_due={'カバルッサ': 100})
    probe = next((o for o in candidates(mem) if o.get('roster_probe')), None)
    assert probe is not None and probe['source'] == 'カバルッサ'
